const S='sphinx',C='chimera',O='orthrus',Z='zombie',H='hydra',Y='cyclops',U='undead-warrior';
const cases=[
 [[S,C,O],2],
 [[S,C,O,Z,H],3],
 [[S,C,O,Z,H,Y],5],
 [[S,S,C,O],4],
 [[S,S,C,O,Z],6],
 [[S,Y],2],
 [[S,U,U,C],2],
 [[S,U,U,U,Y,O,C],3],
 [[S,C,C,C,O,O],2],
 [[C,O,Z],0],
];
function score(army){
  let t=0;
  army.forEach((m,i)=>{
    if(m!==S) return;
    const types=new Set(army.filter((_,j)=>j!==i));
    const n=types.size;
    t += 1 + (n>3 ? 2*(n-3) : 1);
  });
  return t;
}
for(const [a,exp] of cases){
  const got=score(a);
  console.log(got===exp?'OK  ':'FAIL', JSON.stringify(a), 'exp',exp,'got',got);
